from pathlib import Path
import json,html,shutil,zipfile
root=Path(__file__).parent
dist=root/"dist";dist.mkdir(exist_ok=True)
data=json.loads((root/"content.json").read_text(encoding="utf-8-sig"))
E=html.escape
sources=[
("S0","Project conversation · Protecting Wealth from the AI Crisis","https://chatgpt.com/library?file_id=libfile_ec5a2212aa708191b6b4e0acded790d2&account_id=personal","Full conversation reviewed. Source for Steve’s arguments and subjective assessments; earlier assistant assertions are not independent evidence."),
("S1","Microsoft · FY2026 Q4 earnings call","https://www.microsoft.com/en-us/investor/events/fy-2026/earnings-fy-2026-q4","29 July 2026. AI and non-AI infrastructure. Lease-inclusive capex and cash purchases differ; not an AI-only industry total."),
("S2","Brynjolfsson, Rock & Syverson · The Productivity J-Curve","https://www.aeaweb.org/articles?id=10.1257/mac.20180386","AEJ: Macroeconomics, 2021. Complementary intangible investment; does not validate household transfer estimates."),
("S3","U.S. Census · Historical computer use","https://www.census.gov/content/dam/Census/library/working-papers/1992/demo/confpap92.pdf","Historical CPS household ownership. Ownership does not measure career motivation."),
("S4","The Shadow Capital of the Digital Revolution","the_shadow_capital_of_the_digital_revolution.md","Reconciled paper. Original annual arrays retained as provisional; source lineage and attribution remain to be validated."),
("S5","Acemoglu & Pischke · General training and wage structure","https://www.journals.uchicago.edu/doi/10.1086/250071","Journal of Political Economy, 1999. Labour-market frictions affect financing and returns to training."),
("S6","BLS · Productivity and compensation gap","https://www.bls.gov/opub/btn/volume-6/understanding-the-labor-productivity-and-compensation-gap.htm","2017 analysis, 1987–2015 industry data. Selected labour shares are neither current nor economy-wide."),
("S7","Bick, Blandin & Deming · Rapid Adoption of Generative AI","https://www.nber.org/papers/w32966","Working-paper series begun 2024; subsequently published in Management Science. Match survey vintages."),
("S8","Brynjolfsson, Li & Raymond · Generative AI at Work","https://www.nber.org/papers/w31161","2023 working-paper result in one customer-support deployment; not a universal or current-model effect."),
("S9","METR · Early-2025 developer experiment","https://metr.org/blog/2025-07-10-early-2025-ai-experienced-os-dev-study/","16 developers, 246 tasks. Historical and context-specific; read with the update."),
("S10","METR · February 2026 experimental update","https://metr.org/blog/2026-02-24-uplift-update/","Later usefulness likely improved; selection and measurement problems limit updated effect estimates."),
("S11","St. Louis Fed · AI and work productivity","https://www.stlouisfed.org/on-the-economy/2025/feb/impact-generative-ai-work-productivity","27 February 2025. Usage, reported savings and measured productivity differ. Page flags later survey revisions."),
("S12","IEA · Key Questions on Energy and AI","https://www.iea.org/reports/key-questions-on-energy-and-ai/executive-summary","2026 update. 485 TWh in 2025, projected 950 TWh in 2030: all data centres, not AI-only. Conditional projection."),
("S13","Humlum & Vestergaard · Early Danish labour-market evidence","https://bfi.uchicago.edu/working-papers/large-language-models-small-labor-market-effects/","Early earnings/hours evidence. NBER paper subsequently retitled Still Waters, Rapid Currents; no permanent no-effect inference."),
("S14","S&P Global Ratings · Data-centre dashboard","https://press.spglobal.com/2026-10-23-S-P-Global-Ratings-launches-interactive-North-America-data-center-dashboard","23 October 2026. Defined rated universe of 32 transactions and $105.3B issuance, not the whole sector or insurer exposure."),
("S15","NAIC · Private credit and insurance regulation","https://content.naic.org/resource-center/private-credit-insurance-regulation","Liquidity, pricing, capital and complex structures; no specific AI exposure total."),
("S16","U.S. Treasury · Insurance and private credit","https://home.treasury.gov/news/press-releases/sb0493","7 May 2026. Private credit and offshore reserves discussion, not an estimate of AI losses.")
]
flows={
"capital":[("Commit today","Compute · buildings · power"),("Deploy tomorrow","Workflows · quality · demand"),("Recover investment","Cash · margins · useful life")],
"moats":[("Temporary lead","Capability + distribution"),("Competitive pressure","Cost + entry + substitution"),("Durable capture?","Switching costs + execution")],
"solow":[("Model capability","Can it do the task?"),("Human complements","Context + integration + control"),("Net productivity","Accepted output after all costs")],
"households":[("Enterprise ledger","Equipment · software · paid training"),("Household ledger","Hardware · connectivity · unpaid time")],
"shadow":[("Household cost","Attributed cash + valued time"),("Employer benefit","Services + avoided expenditure"),("Net capture?","Counterfactual minus worker returns")],
"knowledge":[("Routine task","The visible job description"),("Situated judgment","Exceptions + dependencies + recovery"),("System performance","Resilience + learning + innovation")],
"enthusiasm":[("Uses the tool","Personal agency + less drudgery"),("Questions the terms","Job risk + workload + control")],
"feedback":[("Delayed deployment","Later receipts or lower utilization"),("Financial pressure","Funding + aging + commitments"),("Wider transmission","Suppliers + credit + investment")],
"wealth":[("Immediate needs","Liquidity + currency + income"),("Possible shocks","Credit + prices + employment"),("Exposure map","Assets + liabilities + correlations")],
"material":[("Component output","Tokens or nameplate capacity"),("Complete service","Reliable workflow or hourly supply"),("System cost","All complements + allocated risk")],
"alternatives":[("Technical constraints","Reliability + data + procurement"),("Incentive constraints","Trust + gains + security"),("Compare explanations","Independent effects + negative cases")],
"settlement":[("Recognize inputs","Pay for learning + expertise"),("Share credible gains","Income + time + agency"),("Evaluate progress","Durable capacity + human benefit")]
}
def flow(id):
    if id=="finance":
        return """<figure class="diagram"><figcaption>FINANCING MAP · contractual links to investigate</figcaption><div class="funding"><div><b>Investors & insurers</b><small>Funds · credit · intermediaries</small></div><div class="flow-arrow">↓</div><div><b>Project entity</b><small>Debt + equity + collateral</small></div><div class="funding-bottom"><div><b>Tenant</b><small>Lease / purchase commitment</small></div><div><b>Guarantor?</b><small>Support / residual-value promise</small></div></div></div></figure>"""
    if id=="distribution":
        return """<figure class="diagram"><figcaption>LABOUR SHARE OF INDUSTRY INCOME · 1987 → 2015</figcaption><div class="bars"><b>Software publishers</b><div class="bar-track"><span style="width:53%">53% · 1987</span></div><div class="bar-track"><span class="later" style="width:30%">30% · 2015</span></div><b>Wireless carriers</b><div class="bar-track"><span style="width:26%">26% · 1987</span></div><div class="bar-track"><span class="later" style="width:10%"></span><label style="left:10%">10% · 2015</label></div></div><p class="figure-note">Shared 0–100% scale. Selected historical industries, not an aggregate estimate or causal attribution. <a href="#S6">BLS · S6</a></p></figure>"""
    if id=="standoff":
        return """<figure class="diagram"><figcaption>THE COOPERATION LOOP · a testable hypothesis</figcaption><div class="loop"><div><b>Expected share<br>of gains</b><small>Pay · time · security · control</small></div><span>→</span><div><b>Willingness<br>to contribute</b><small>Learning · context · evaluation</small></div><span>→</span><div><b>Quality of<br>deployment</b><small>Accepted output · lower cost</small></div></div><p class="feedback-line">↳ Realized gains and credible commitments feed back into expectations.</p></figure>"""
    if id=="test":
        return """<figure class="diagram"><figcaption>PROPOSED EXPERIMENT · same tools and tasks, different credible terms</figcaption><div class="trial"><div class="common"><b>Common paid rollout</b><small>Training · support · task suitability</small></div><div class="arms"><div><b>Ordinary terms</b><small>Ethically acceptable baseline</small></div><div><b>Benefit-sharing terms</b><small>Credible stake + transition agreement</small></div></div><div class="common"><b>Compare outcomes</b><small>Cooperation · quality · worker welfare · net cost</small></div></div></figure>"""
    parallel=id in ("households","enthusiasm")
    return '<figure class="diagram"><figcaption>ARGUMENT MAP · '+("parallel contributions or attitudes" if parallel else "proposed dependency, not a measured effect")+'</figcaption><div class="nodes '+("parallel" if parallel else "")+'">'+"".join('<div class="node"><span>'+f"{i+1:02}"+'</span><b>'+E(a)+'</b><small>'+E(b)+'</small></div>' for i,(a,b) in enumerate(flows[id]))+'</div></figure>'
nav="";sections="";outline="# The AI Standoff: Who pays for progress?\n\n"+data["thesis"]+"\n\n"+data["scope"]+"\n\n"
count=0
for i,ch in enumerate(data["chapters"],1):
    nav+=f'<a href="#{ch["id"]}"><span>{i:02}</span>{E(ch["title"])}</a>'
    sections+=f'<section class="chapter" id="{ch["id"]}"><header><p class="eyebrow">CHAPTER {i:02} <span>/ 16</span></p><h2>{E(ch["title"])}</h2><p class="deck">{E(ch["deck"])}</p></header>'+flow(ch["id"])
    outline+=f'## {i:02}. {ch["title"]}\n\n{ch["deck"]}\n\n'
    for p in ch["points"]:
        count+=1
        refs=' · '.join(f'<a href="#{s}">{s}</a>' for s in p["refs"])
        search=E(" ".join([p["title"],p["text"]]+p["bullets"]).lower(),quote=True)
        sections+=f'<article class="point" id="point-{count}" data-search="{search}"><span class="point-num">{count:02}</span><div><p class="kind">{p["kind"]}</p><h3><a href="#point-{count}">{E(p["title"])}</a></h3><p class="explanation">{E(p["text"])}</p><ul>'+"".join(f'<li>{E(x)}</li>' for x in p["bullets"])+'</ul>'+(f'<p class="refs">Sources {refs}</p>' if refs else '')+'</div></article>'
        outline+=f'### {count}. {p["title"]} [{p["kind"]}]\n\n{p["text"]}\n\n'+"\n".join("- "+x for x in p["bullets"])+"\n\n"+("Sources: "+", ".join(p["refs"])+"\n\n" if p["refs"] else "")
    sections+='</section>'
outline+="## Sources\n\n"+"\n".join(f"- {sid}: [{title}]({url}) — {note}" for sid,title,url,note in sources)
ledger="".join(f'<article class="source" id="{sid}"><h3><span>{sid}</span><a href="{E(url,quote=True)}" '+('target="_blank" rel="noopener"' if url.startswith("http") else '')+f'>{E(title)} ↗</a></h3><p>{E(note)}</p></article>' for sid,title,url,note in sources)
methods="""<section class="appendix" id="methods"><p class="eyebrow">METHODS / RECONCILED INPUTS</p><h2>A consistent calculation.<br>An open research question.</h2><p>The original arrays cover the United States, 1980–2010. Totals are cumulative nominal USD. Arithmetic is reconciled; historical inputs and attribution parameters remain provisional. Combined gross cost is not a measured uncompensated transfer.</p><div class="calculator"><h3>Explore the assumptions</h3><div class="controls"><label>Career attribution · <output id="av">40%</output><input id="attribution" type="range" min="0" max="100" step="5" value="40"></label><label>Learning time · <output id="hv">1.5 h/week</output><input id="hours" type="range" min="0" max="4" step=".1" value="1.5"></label><label>Time valuation · <output id="wv">75% of wage</output><input id="wage" type="range" min="0" max="100" step="5" value="75"></label></div><div class="results" aria-live="polite"><div><span>Direct household cost</span><strong id="cash">$707.20B</strong></div><div><span>Imputed learning time</span><strong id="time">$1,904.49B</strong></div><div><span>Combined gross cost</span><strong id="combined">$2,611.69B</strong></div><div><span>Relative to $9,852B corporate IT</span><strong id="ratio">26.51%</strong></div></div><p class="fine">Deterministic scenario, not a confidence interval. Includes ancillary outlays conditional on no overlap. Assumes 52 weeks/year. No extra 1.815 multiplier.</p></div><h3>What changed</h3><div class="table-scroll"><table><thead><tr><th>Quantity</th><th>Exported headline</th><th>Reconciled baseline</th></tr></thead><tbody><tr><td>Corporate IT outlays</td><td>$4,651.00B</td><td>$9,852.00B</td></tr><tr><td>Direct household cost</td><td>$842.36B</td><td>$707.20B with ancillary</td></tr><tr><td>Time value</td><td>$3,479.41B</td><td>$1,904.49B without multiplier</td></tr><tr><td>Combined / corporate</td><td>Inconsistent basis</td><td>26.51%</td></tr></tbody></table></div><p>The printed direct rows exclude ancillary spending and sum to $591.36B. Including the code’s ancillary array produces $707.20B. Excluding ancillary gives $2,495.85B combined, or 25.33%. No input was tuned to preserve a previous headline.</p><details><summary>What remains to establish</summary><ol><li>Source lineage and interpolation for every annual input.</li><li>Work attribution, exposure and unpaid learning hours.</li><li>No overlap among hardware, materials, tuition and ancillary costs.</li><li>Reimbursement, private benefits and worker returns.</li><li>The counterfactual for employer benefit and net capture.</li></ol></details><div class="downloads"><a href="ai_standoff_outline.md" download>Complete point-form narrative ↓</a><a href="the_shadow_capital_of_the_digital_revolution.md" download>Reconciled paper ↓</a><a href="shadow_capital_annual.csv" download>Annual data ↓</a><a href="shadow_capital_model.zip" download>Model + inputs ↓</a></div></section>"""
template="""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The AI Standoff — Who Pays for Progress?</title><meta name="description" content="A visual research narrative about AI investment, household-financed computerization and the terms of technological adoption."><style>__CSS__</style></head><body><a class="skip" href="#story">Skip to narrative</a><header class="top"><a class="brand" href="#top"><i>Sc.</i><span>AI CAPEX / RESEARCH ATLAS</span></a><nav aria-label="Main"><a href="#story">Narrative</a><a href="#methods">Methods</a><a href="#sources">Sources</a></nav></header><div id="progress" aria-hidden="true"></div><main><section class="hero" id="top"><div class="hero-inner"><div><p class="eyebrow">A WORKING THEORY OF THE NEXT TRANSITION</p><h1>The AI<br><em>Standoff.</em></h1><p class="subtitle">Who pays for progress?</p><p class="thesis">__THESIS__</p><a class="cta" href="#story">Follow the argument ↘</a></div><div class="hero-art" aria-hidden="true"><div class="orbit"><span class="orb-label label1">CAPITAL COMMITTED</span><strong>Who supplies<br>the missing<br>complements?</strong><span class="orb-label label2">KNOWLEDGE REQUIRED</span><span class="orb-label label3">RETURNS EXPECTED</span></div></div></div><div class="hero-foot"><span>16 chapters</span><span>64 propositions</span><span>Evidence + counterarguments</span><span>Working edition · 29 October 2026</span></div></section><section class="intro"><h2>An investment story.<br>A labour history.<br>A bargaining problem.</h2><div><p>The narrative begins with money committed to AI, follows the human inputs behind the previous computing transition, then returns to whether the next transition can earn the cooperation it requires.</p><p class="scope">__SCOPE__</p><p class="scope">Labels distinguish evidence, mechanisms, perspectives, hypotheses and proposals. Schematics explain relationships; they do not measure effect sizes. Switch to the outline to inspect every point and its qualifications.</p></div></section><div class="shell" id="story"><aside class="rail"><p class="eyebrow">THE ARGUMENT</p>__NAV__<a href="#methods"><span>+</span>Methods & reconciliation</a><a href="#sources"><span>↗</span>Source ledger</a></aside><div class="reading"><div class="toolbar"><div class="modes" role="group" aria-label="Reading format"><button type="button" data-mode="story" aria-pressed="true">Narrative</button><button type="button" data-mode="outline" aria-pressed="false">Point-form outline</button></div><label class="find"><span>Find a point</span><input id="search" type="search" placeholder="Learning, trust, financing…"></label><span id="search-status" role="status"></span></div><p id="no-results" hidden>No matching points. Try a broader term.</p>__SECTIONS____METHODS__<section class="appendix" id="sources"><p class="eyebrow">EVIDENCE / SOURCE LEDGER</p><h2>Follow the claim<br>to its source.</h2><p>Each source supports its attached claim, not the entire thesis. Political arguments and the provisional model have different roles from empirical findings.</p>__SOURCES__</section></div></div></main><footer><div><b>The AI Standoff</b> · research synthesis / working edition</div><div>Useful capacity. Accountable costs. A credible share of the gains.</div></footer><script>__JS__</script></body></html>"""
out=template
for k,v in {"CSS":(root/"styles.css").read_text(encoding="utf-8"),"JS":(root/"app.js").read_text(encoding="utf-8"),"THESIS":E(data["thesis"]),"SCOPE":E(data["scope"]),"NAV":nav,"SECTIONS":sections,"METHODS":methods,"SOURCES":ledger}.items():out=out.replace("__"+k+"__",v)
assert "__CSS__" not in out and count==64
assert all(f'id="{s}"' in out for s,_,_,_ in sources)
(dist/"index.html").write_text(out,encoding="utf-8")
(dist/"ai_standoff_outline.md").write_text(outline,encoding="utf-8")
shutil.copy2(root.parent.parent/"research/the_shadow_capital_of_the_digital_revolution.md",dist)
shutil.copy2(root.parent.parent/"research/shadow_capital_annual.csv",dist)
with zipfile.ZipFile(dist/"shadow_capital_model.zip","w",zipfile.ZIP_DEFLATED) as z:
    for name in ("shadow_capital_model.py","reconciled_inputs.json","shadow_capital_annual.csv","reconciliation.json"):z.write(root.parent.parent/"research"/name,name)
test=dist/"test.txt"
if test.exists():test.unlink()
(root/"README.md").write_text("# The AI Standoff\n\nBuild: python build.py\n\nServe dist with a static HTTP server. No dependencies.\n\ncontent.json is the canonical 64-point source. The outline and site are generated from it. Reconciliation is not source authentication.\n",encoding="utf-8")
print(json.dumps(dict(chapters=len(data["chapters"]),points=count,html_bytes=len(out.encode()),outline_words=len(outline.split()),sources=len(sources))))
